settings.custom_css:
/* =========================================
   Global Reset & Variables
   ========================================= */
* {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
}

body {
    background-color: #f9f5f0; /* Soft spiritual ivory */
    font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
    color: #333;
    line-height: 1.6;
    padding: 30px 15px;
}

/* =========================================
   Main Wrapper
   ========================================= */
.aacharya-page-wrapper {
    max-width: 1100px;
    margin: 0 auto;
    background: #ffffff;
    border-radius: 12px;
    box-shadow: 0 12px 40px rgba(0, 0, 0, 0.08);
    overflow: hidden;
    border-top: 6px solid #e65c00; /* Deep Saffron/Orange */
}

/* =========================================
   Header Banner
   ========================================= */
.peetham-banner {
    background: linear-gradient(to right, #fff5e6, #ffedd6);
    text-align: center;
    padding: 35px 20px;
    border-bottom: 2px solid #f2dcb3;
}

.sub-heading {
    color: #8c4000;
    font-size: 1.4em;
    font-weight: 600;
    margin-bottom: 5px;
}

.main-heading {
    color: #cc4400;
    font-size: 2.8em;
    font-weight: bold;
    letter-spacing: 1px;
}

.tagline {
    color: #666;
    font-size: 1.1em;
    font-style: italic;
    margin-top: 8px;
}

/* =========================================
   Content Layout (Flexbox)
   ========================================= */
.content-container {
    display: flex;
    flex-wrap: wrap;
    padding: 40px;
    gap: 50px;
}

/* =========================================
   Left Side: Profile Image
   ========================================= */
.profile-section {
    flex: 1;
    min-width: 320px;
    display: flex;
    flex-direction: column;
    align-items: center;
}

.portrait-frame {
    width: 280px;
    height: 350px;
    border-radius: 10px;
    border: 6px solid #f2e3d5;
    box-shadow: 0 10px 25px rgba(230, 92, 0, 0.15);
    overflow: hidden;
    background-color: #fff;
    margin-bottom: 25px;
}

.portrait-frame img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    transition: transform 0.5s ease;
}

.portrait-frame:hover img {
    transform: scale(1.06);
}

.name-badge {
    text-align: center;
    background: #fffaf0;
    padding: 20px;
    border-radius: 8px;
    width: 100%;
    border-left: 5px solid #e65c00;
    box-shadow: 0 4px 15px rgba(0, 0, 0, 0.04);
}

.name-badge h3 {
    color: #cc4400;
    font-size: 1.5em;
    margin-bottom: 2px;
}

.english-name {
    display: block;
    color: #666;
    font-size: 0.9em;
    margin-bottom: 10px;
}

.title-line {
    display: inline-block;
    background-color: #e65c00;
    color: #fff;
    padding: 5px 15px;
    border-radius: 20px;
    font-size: 0.95em;
    font-weight: 600;
}

/* =========================================
   Right Side: Biography Info
   ========================================= */
.biography-section {
    flex: 2;
    min-width: 320px;
}

.info-card {
    margin-bottom: 35px;
}

/* Special Highlight for the new Reverence Section */
.special-highlight {
    background-color: #fffdf8;
    padding: 20px;
    border-radius: 8px;
    border-left: 4px solid #ff9933;
    box-shadow: 0 4px 10px rgba(0,0,0,0.02);
}

.section-title {
    color: #d9531e;
    font-size: 1.6em;
    border-bottom: 2px dashed #f2cca3;
    padding-bottom: 10px;
    margin-bottom: 15px;
}

.info-card p {
    font-size: 1.15em;
    line-height: 1.8;
    text-align: justify;
    color: #444;
}

/* =========================================
   Quick Facts Section (Grid)
   ========================================= */
.quick-facts {
    background-color: #faf5eb;
    padding: 40px;
    border-top: 2px solid #f2dcb3;
}

.text-center {
    text-align: center;
    border-bottom: none;
    margin-bottom: 30px;
}

.facts-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
    gap: 20px;
}

.fact-item {
    background: #ffffff;
    padding: 20px;
    border-radius: 8px;
    text-align: center;
    box-shadow: 0 4px 10px rgba(0,0,0,0.03);
    border-bottom: 3px solid #ffaa66;
    transition: transform 0.3s ease;
}

.fact-item:hover {
    transform: translateY(-5px);
}

.fact-item .icon {
    font-size: 2em;
    display: block;
    margin-bottom: 10px;
}

.fact-item strong {
    color: #cc4400;
    font-size: 1.1em;
    display: block;
    margin-bottom: 5px;
}

.fact-item p {
    color: #555;
    font-size: 0.95em;
}

/* =========================================
   Responsive Adjustments (Mobile/Tablets)
   ========================================= */
@media (max-width: 800px) {
    .content-container {
        flex-direction: column;
        padding: 30px 20px;
    }

    .main-heading {
        font-size: 2.2em;
    }

    .portrait-frame {
        width: 240px;
        height: 300px;
    }

    .info-card p {
        text-align: left;
    }
}
